    for tid, info in tasks.items():
        submit_time = None
        running_task = None  # (start_time, end_time, machine)

        for t, e, m, p, c, mem, rt in info['events']:
            if e == 'submit' and submit_time is None:
                submit_time = t
            if e == 'start':
                running_task = (t, t + rt, m)
            if e == 'finish' or e == 'evict' or e == 'fail':
                if running_task and running_task[0] <= t:
                    running_task = None

        if submit_time is None or submit_time > time:
            continue

        if running_task and running_task[0] <= time < running_task[1]:
            # Still running (check if it finished by 'time')
            # Actually need to check if there's a finish/evict/fail event at or before 'time'
            has_ended = False
            for t2, e2, m2, p2, c2, mem2, rt2 in info['events']:
                if e2 in ['finish', 'evict', 'fail'] and t2 <= time and t2 > running_task[0]:
                    has_ended = True
                    break
            if not has_ended:
                running.append((tid, p, submit_time, c, mem, rt, running_task[2]))
            else:
                # Task was stopped, back in queue
                in_queue.append((tid, p, submit_time, c, mem, rt))
        elif running_task is None:
            # Check if it ever started
            ever_started = any(e == 'start' for t, e, m, p, c, mem, rt in info['events'])
            if ever_started:
                # Started and finished/stopped
                pass
            else:
                in_queue.append((tid, p, submit_time, c, mem, rt))
        elif running_task and running_task[1] <= time:
            # Finished before 'time'
            pass

    # Sort queue: higher priority first, then earlier submission, then lower task id
    in_queue.sort(key=lambda x: (-x[1], x[2], x[0]))
    return in_queue, running

