# Parse all events
events = []
for row in rows:
    event = {
        'time': int(row[0]),
        'task': row[1],
        'job': row[2],
        'priority': int(row[3]),
        'cpu': int(row[4]),
        'memory': int(row[5]),
        'run_time': int(row[6]),
        'event_type': row[7],
        'machine': row[8]
    }
    events.append(event)

def event_order(e):
    order = {'finish': 0, 'fail': 1, 'start': 3, 'evict': 3, 'submit': 2}
    return (e['time'], order.get(e['event_type'], 4), e['task'])

events_sorted = sorted(events, key=event_order)

def get_machine_state_at(time_limit):
    state = {m: [] for m in machines}

    for e in events_sorted:
        if e['time'] > time_limit:
            break

        if e['event_type'] == 'start':
            state[e['machine']].append({
                'task': e['task'],
                'cpu': e['cpu'],
                'mem': e['memory'],
                'end_time': e['time'] + e['run_time']
            })
        elif e['event_type'] in ['finish', 'evict', 'fail']:
            state[e['machine']] = [t for t in state[e['machine']] if t['task'] != e['task']]

    # Filter out tasks that have ended by time_limit
    for m in state:
        state[m] = [t for t in state[m] if t['end_time'] > time_limit]

    return state

